const LOCALES = [
  ['zh-Hans','简体中文'], ['ja','日本語'], ['zh-Hant','繁體中文'],
  ['en','English'], ['fil','Filipino'], ['vi','Tiếng Việt'],
  ['id','Bahasa Indonesia'], ['th','ไทย'], ['hi','हिन्दी'], ['ko','한국어']
];
const baseWords = groups.flatMap(g => g[3]);
const wordIndex = new Map(baseWords.map((row, i) => [row[0], i]));
function normalizeLocale(value) {
  const v = String(value || '').toLowerCase();
  if (v === 'zh' || v.startsWith('zh-')) return /hant|tw|hk|mo/.test(v) ? 'zh-Hant' : 'zh-Hans';
  if (v === 'tl' || v.startsWith('tl-')) return 'fil';
  return LOCALES.find(([code]) => v === code.toLowerCase() || v.startsWith(code.toLowerCase() + '-'))?.[0] || null;
}
function initialLocale() {
  const shared = normalizeLocale(new URLSearchParams(location.search).get('lang'));
  if (shared) return shared;
  try { const saved = normalizeLocale(localStorage.getItem('signtoki-lang')); if (saved) return saved; } catch {}
  for (const preference of navigator.languages || [navigator.language]) {
    const match = normalizeLocale(preference); if (match) return match;
  }
  return 'en';
}
let lang=initialLocale(),mode='meaning',set=Math.max(0,Math.min(7,Number(new URLSearchParams(location.search).get('set'))||0)),screen='home',index=0,score=0,answered=false,selectedAnswer=null,choices=[],round=[];
const $=s=>document.querySelector(s);
function t(english,korean) { return I18N[lang].ui[english] ?? (lang === 'ko' ? korean : english); }
function format(english, values) { return Object.entries(values).reduce((text,[key,value]) => text.replaceAll('{'+key+'}',String(value)),t(english)); }
function topic(g) { return lang === 'ko' ? g[1] : lang === 'en' ? g[0] : I18N[lang].topics[groups.indexOf(g)]; }
function meaning(row) { return lang === 'ko' ? row[3] : lang === 'en' ? row[2] : I18N[lang].words[wordIndex.get(row[0])]; }
function note(row) { return lang === 'ko' ? row[3]+'.' : lang === 'en' ? row[4] : I18N[lang].notes[wordIndex.get(row[0])]; }
const app=$('#app');
function speak(word){if(!('speechSynthesis'in window)){toast(t('Audio is not supported by this browser.','이 브라우저는 발음을 지원하지 않습니다.'));return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='ko-KR';u.rate=.8;const v=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('ko'));if(v)u.voice=v;window.speechSynthesis.speak(u)}
function toast(s){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=s;d.setAttribute('role','status');document.body.append(d);setTimeout(()=>d.remove(),3500)}
function render(){document.documentElement.lang=lang;$('#lang').value=lang;$('#languageLabel').textContent=t('Language');$('#lang').setAttribute('aria-label',t('Language'));document.title='SignToki — '+t('A little Korean. A whole new street.');document.querySelector('meta[name=description]').content=t('A little curiosity is all you need. Read your way through Korea.');$('#travelerFooter').textContent=t('Made for curious travelers ♡');$('#playNav').textContent=t('Play','게임');$('#guideNav').textContent=t('Street guide','거리 안내');$('#playNav').className=screen==='guide'?'':'nav-active';$('#guideNav').className=screen==='guide'?'nav-active':'';$('#footerText').textContent=t('A little Korean. A whole new street.','조금의 한국어, 새롭게 보이는 거리.');if(screen==='home')home();else if(screen==='quiz')quiz();else if(screen==='result')result();else guide()}
function home(){app.innerHTML=`<div class="intro"><div><div class="eyebrow">${t('YOUR NEXT STOP: KOREA')}</div><h1>${t('New street. <em>Familiar signs.</em>','새로운 거리. <em>익숙한 간판.</em>')}</h1><p>${t('A little curiosity is all you need. Read your way through Korea.','호기심 하나면 충분해요. 길에서 만나는 한국어를 읽어 보세요.')}</p></div><div class="stamp"><span>◷ ${t('3 minutes','3분')}</span><span>${t('5 signs','간판 5개')}</span><span>${t('No sign-up','가입 없이')}</span></div></div><div class="game-layout"><div class="street"><img src="street-print.webp" alt="${t('An illustrated fictional Seoul street with three storefronts','가상의 서울 거리와 세 개의 가게 일러스트')}"><div class="street-top"><span class="location">⌖ ${t('A little street in Seoul','서울의 작은 골목')}</span><button class="sound" id="streetAudio" aria-label="${t('Hear pharmacy in Korean','약국 발음 듣기')}">♪</button></div><button class="sign one" data-start="1">카페</button><button class="sign two" data-start="0">약국</button><button class="sign three" data-start="0" data-index="1">편의점</button><div class="street-bottom">${t('See a sign you know? <b>Give it a try.</b>','아는 간판이 있나요? <b>눌러 보세요.</b>')}</div></div><aside class="side"><span class="pill">${String(set+1).padStart(2,'0')} / 08</span><h2>${topic(groups[set])}</h2><p>${t('Five signs you’ll be glad you know. One small step closer to feeling at home.','알아두면 반가운 간판 다섯 개. 낯선 여행지가 조금 더 익숙해집니다.')}</p><div class="mode-label">${t('How would you like to play?','어떻게 시작할까요?')}</div><div class="modes"><button data-mode="meaning" class="${mode==='meaning'?'selected':''}">${t('Guess the meaning','뜻 맞히기')}</button><button data-mode="reading" class="${mode==='reading'?'selected':''}">${t('Read the sign','읽기')}</button></div><div class="mode-desc">${mode==='meaning'?t('Match the Korean sign to the right place.','간판을 보고 어떤 곳인지 맞혀 보세요.'):t('Match the letters to their pronunciation.','한글에 맞는 발음 표기를 골라 보세요.')}</div><button class="primary" id="start">${t('Let’s hit the street','거리로 나가 볼까요')}</button><div class="subnote">${t('5 questions · About 3 minutes · Always free','5문제 · 약 3분 · 무료')}</div></aside></div><div class="below-title"><h3>${t('Pick your kind of street','오늘은 어떤 길을 걸을까요')}</h3><span>${t('8 little adventures · 40 signs','8개 주제 · 40개 간판')}</span></div><div class="sets">${groups.map((g,i)=>`<button class="set ${i===set?'active':''}" data-set="${i}"><span class="set-icon">${g[2]}</span><span><b>${topic(g)}</b><small>${t('5 signs · Beginner friendly','간판 5개 · 초급')}</small></span></button>`).join('')}</div><div class="how"><strong>${t('A tiny game. A real travel skill.','작은 게임으로 배우는 진짜 여행의 감각.')}</strong><span><i>①</i>${t('Spot a sign','간판 발견')}</span><span><i>②</i>${t('Take a guess','정답 선택')}</span><span><i>③</i>${t('Make it yours','발음과 뜻 복습')}</span></div>`;$('#start').onclick=()=>start(set);$('#streetAudio').onclick=()=>speak('약국');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;home()});document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>{set=+b.dataset.set;home()});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(+b.dataset.start,+b.dataset.index||0))}
function start(s,i=0){set=s;index=0;score=0;answered=false;selectedAnswer=null;screen='quiz';round=[...groups[s][3].slice(i),...groups[s][3].slice(0,i)];makeChoices();render();window.scrollTo({top:0,behavior:'smooth'})}
function makeChoices(){const row=round[index];const all=groups.flatMap(g=>g[3]);choices=[row,...all.filter(r=>r[0]!==row[0]).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5)}
function quiz(){let row=round[index];app.innerHTML=`<div class="quiz"><div class="quiz-top"><button class="text-button" id="back">${t('Back to the street','거리로 돌아가기')}</button><span>${index+1} / 5 · ${topic(groups[set])}</span></div><div class="progress">${Array.from({length:5},(_,i)=>`<span class="${i<=index?'done':''}"></span>`).join('')}</div><div class="quiz-card"><div class="eyebrow">${t('A SIGN ALONG THE WAY','길에서 만난 간판')}</div><div class="big-sign">${row[0]}</div><h2>${mode==='meaning'?t('What does this sign mean?','이 간판은 무슨 뜻일까요?'):t('How do you read this sign?','이 간판을 어떻게 읽을까요?')}</h2><div class="answers">${choices.map((r,i)=>`<button class="answer" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${mode==='reading'?r[1]:meaning(r)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div></div></div>`;$('#back').onclick=()=>{screen='home';render()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));answered=false;if(selectedAnswer!==null)answer(selectedAnswer,true)}
function answer(n,replay=false){if(answered)return;answered=true;selectedAnswer=n;const row=round[index],right=choices[n][0]===row[0];if(right&&!replay)score++;document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(choices[+b.dataset.answer][0]===row[0])b.classList.add('correct');else if(+b.dataset.answer===n)b.classList.add('wrong')});$('#feedback').innerHTML=`<div class="feedback"><b>${right?t('You found it!','맞혔어요!'):t('A new sign to remember.','새로운 간판을 알아볼까요.')}</b><br><strong>${row[0]}</strong> · ${row[1]} · ${meaning(row)} <button class="text-button" id="listen">♪ ${t('Listen','발음 듣기')}</button><br>${note(row)}<br><small>${t('Also look out for','함께 알아두기')}: ${row[5]}</small><button class="primary" id="next">${index===4?t('See my street signs','오늘 읽은 간판 보기'):t('Next sign','다음 간판')}</button></div>`;$('#listen').onclick=()=>speak(row[0]);$('#next').onclick=()=>{selectedAnswer=null;index++;if(index===5)screen='result';else makeChoices();render()}}
function result(){app.innerHTML=`<div class="quiz"><div class="quiz-card"><span class="pill">${String(score).padStart(2,'0')} / 05</span><h1>${t('Look at you, street reader.','이제 간판이 눈에 들어오죠?')}</h1><p>${format('You read 5 signs. {score} out of 5 correct.',{score})}</p><div class="review">${round.map((r,i)=>`<div class="review-item"><div><b>${r[0]}</b><br><small>${r[1]} · ${meaning(r)}</small></div><button class="text-button" data-listen="${i}" aria-label="${format('Listen to {word}',{word:r[0]})}">♪</button></div>`).join('')}</div><button class="primary" id="another">${t('Explore the next street','다음 거리 둘러보기')}</button><div class="actions" style="margin-top:16px"><button class="secondary" id="share">${t('Share this set','이 세트 공유')}</button><button class="secondary" id="home">${t('Pick a street','주제 선택')}</button></div></div></div>`;document.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>speak(round[+b.dataset.listen][0]));$('#another').onclick=()=>start((set+1)%8);$('#home').onclick=()=>{screen='home';render()};$('#share').onclick=async()=>{let u=new URL(location.href);u.searchParams.set('set',set);u.searchParams.set('lang',lang);try{if(navigator.share)await navigator.share({title:'SignToki',text:t('Can you read these 5 Korean signs?','한국 간판 다섯 개, 읽을 수 있나요?'),url:u.href});else{await navigator.clipboard.writeText(u.href);toast(t('Set link copied!','세트 링크를 복사했어요!'))}}catch(e){if(e.name!=='AbortError'){prompt(t('Copy this set link','세트 링크를 복사하세요'),u.href)}}}}
function guide(){app.innerHTML=`<div class="intro"><div><div class="eyebrow">${t('A POCKET GUIDE TO KOREA')}</div><h1>${t('The street makes <em>more sense.</em>','거리가 조금 더 <em>친숙해져요.</em>')}</h1></div></div><p class="guide-lead">${t('Start with 약국 for medicine, 편의점 for everyday essentials, and 출구 for your way out. Read the letters, listen to the pronunciation, then try spotting the same words on your trip. These are fictional signs, using everyday Korean expressions.','약은 약국에서, 간식과 생활용품은 편의점에서. 지하철을 나갈 때는 출구를 찾아보세요. 글자를 읽고 발음을 들은 뒤 여행에서 같은 표현을 찾아보세요. 실제 상호가 아닌 일상적인 한국어 표현을 사용한 가상 간판입니다.')}</p><div class="guide-grid">${groups.flatMap(g=>g[3]).map((r,i)=>`<article class="guide-item"><h3>${r[0]}</h3><small>${r[1]}</small><p><strong>${meaning(r)}</strong><br>${note(r)}</p><button class="text-button" data-guide-listen="${i}">♪ ${t('Listen','듣기')}</button></article>`).join('')}</div>`;document.querySelectorAll('[data-guide-listen]').forEach(b=>b.onclick=()=>speak(groups.flatMap(g=>g[3])[+b.dataset.guideListen][0]))}
$('#lang').innerHTML=LOCALES.map(([code,label])=>`<option value="${code}" lang="${code}">${label}</option>`).join('');$('#lang').onchange=()=>{lang=$('#lang').value;try{localStorage.setItem('signtoki-lang',lang)}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render()};$('#playNav').onclick=()=>{screen='home';render()};$('#guideNav').onclick=()=>{screen='guide';render()};render();
if(navigator.modelContext?.registerTool){navigator.modelContext.registerTool({name:'start_sign_round',description:'Start a five-question Korean street sign game with a topic from 0 to 7.',inputSchema:{type:'object',properties:{topic:{type:'integer',minimum:0,maximum:7}},required:['topic']},execute:async({topic})=>{start(Math.max(0,Math.min(7,topic)));return {content:[{type:'text',text:'Round started.'}]}}})}
